    const applyMarkdownFormat = (format) => { if (!editor) return; if (format === 'bold') applyInlineFormat('**', '**', t.boldPlaceholder); if (format === 'italic') applyInlineFormat('*', '*', t.italicPlaceholder); if (format === 'code') applyInlineFormat('`', '`', t.codePlaceholder); if (format === 'h1') applyBlockFormat('# ', t.headingPlaceholder); if (format === 'h2') applyBlockFormat('## ', t.heading2Placeholder); if (format === 'h3') applyBlockFormat('### ', 'H3'); if (format === 'quote') applyBlockFormat('> ', t.quotePlaceholder); if (format === 'bullet') applyBlockFormat('- ', t.listItemPlaceholder); if (format === 'ordered') applyBlockFormat('1. ', t.listItemPlaceholder); if (format === 'link') { const start = editor.selectionStart; const end = editor.selectionEnd; const selected = editor.value.slice(start, end) || t.linkTextPlaceholder; const replacement = `[${selected}](https://)`; const urlStart = start + selected.length + 3; replaceEditorSelection(replacement, start, end, urlStart, urlStart + 8); } };
    async function uploadMedia(file, isImage = false) { if (uploadingImage || !editor || !file) return; const uploading = isImage ? t.imageUploading : t.fileUploading; const uploaded = isImage ? t.imageUploaded : t.fileUploaded; const failed = isImage ? t.imageUploadFailed : t.fileUploadFailed; if (file.size > 10 * 1024 * 1024) { showToast(t.attachmentTooLarge, 'error'); return; } uploadingImage = true; state.textContent = uploading; try { const data = new FormData(); data.append('_token', csrfToken); data.append('file', file, file.name || (isImage ? 'image.png' : 'attachment')); const response = await fetch('{{ route('media.store') }}', { method: 'POST', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': csrfToken }, body: data }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(result.errors?.file?.[0] || result.errors?.image?.[0] || result.message || failed); const start = editor.selectionStart; const end = editor.selectionEnd; replaceEditorSelection(result.markdown, start, end, start, start + result.markdown.length); showToast(result.isImage ? t.imageUploaded : uploaded); } catch (error) { state.textContent = failed; showToast(error.message || failed, 'error'); } finally { uploadingImage = false; } }
    const uploadClipboardImage = (image) => uploadMedia(image, true);
    const enhanceImages = (root) => { if (!root) return; root.querySelectorAll('img').forEach((image) => { if (image.closest('.note-image')) return; const imageElement = image.closest('a') || image; const wrapper = document.createElement('span'); wrapper.className = 'note-image'; imageElement.parentNode.insertBefore(wrapper, imageElement); wrapper.append(imageElement); const download = document.createElement('a'); download.className = 'image-download'; download.href = image.currentSrc || image.src; download.download = ''; download.title = t.downloadImage; download.setAttribute('aria-label', t.downloadImage); download.textContent = '↓'; wrapper.append(download); }); };
    const bindEditor = () => { editor = document.getElementById('editor'); state = document.getElementById('save-state'); editorLayout = document.getElementById('editor-layout'); editNoteButton = document.getElementById('edit-note'); readNoteButton = document.getElementById('read-note'); saveNoteButton = document.getElementById('save-note'); const attachmentButton = document.getElementById('attach-file'); const attachmentInput = document.getElementById('attachment-file'); if (!editor || !state || !editorLayout) return; lastSaved = editor.value; editor.addEventListener('input', () => { state.textContent = t.unsavedChanges; }); editor.addEventListener('paste', (event) => { const image = [...(event.clipboardData?.items || [])].find((item) => item.type.startsWith('image/'))?.getAsFile(); if (!image) return; event.preventDefault(); uploadClipboardImage(image); }); editor.addEventListener('dragover', (event) => { if (event.dataTransfer?.files.length) event.preventDefault(); }); editor.addEventListener('drop', (event) => { const file = event.dataTransfer?.files?.[0]; if (!file) return; event.preventDefault(); uploadMedia(file, file.type.startsWith('image/')); }); attachmentButton?.addEventListener('click', () => attachmentInput?.click()); attachmentInput?.addEventListener('change', () => { const file = attachmentInput.files?.[0]; attachmentInput.value = ''; if (file) uploadMedia(file); }); editNoteButton?.addEventListener('click', () => setEditorMode(true)); readNoteButton?.addEventListener('click', () => setEditorMode(false)); saveNoteButton?.addEventListener('click', async (event) => { event.preventDefault(); if (!await saveQuietly()) { showToast(lastSaveError || t.couldNotSave, 'error'); return; } try { await refreshPreview(); showToast(t.changesSaved); } catch (_) { showToast(t.couldNotRefreshPreview, 'error'); } }); editorLayout.querySelectorAll('[data-format]').forEach((button) => { if (button.dataset.formatBound) return; button.dataset.formatBound = 'true'; button.addEventListener('click', () => applyMarkdownFormat(button.dataset.format)); }); };
    async function saveQuietly() { if (!editor || editor.value === lastSaved) return true; if (saving) return false; saving = true; lastSaveError = ''; state.textContent = t.saving; try { const response = await fetch(document.getElementById('note-form').action, { method:'POST', headers:{'Accept':'application/json','X-CSRF-TOKEN':csrfToken}, body:new URLSearchParams({_token:csrfToken,_method:'PUT',content:editor.value}) }); const result = response.ok ? null : await response.json().catch(() => ({})); if (!response.ok) throw new Error(result.message || result.errors?.content?.[0] || t.couldNotSave); lastSaved = editor.value; state.textContent = t.saved; return true; } catch (error) { lastSaveError = error.message || t.couldNotSave; state.textContent = lastSaveError; return false; } finally { saving = false; } }
    async function refreshPreview() { const response = await fetch(document.getElementById('note-form').action, { headers: { 'X-Requested-With': 'XMLHttpRequest' } }); if (!response.ok) throw new Error(); const nextPreview = new DOMParser().parseFromString(await response.text(), 'text/html').querySelector('.preview-pane'); const currentPreview = editorLayout?.querySelector('.preview-pane'); if (!nextPreview || !currentPreview) throw new Error(); currentPreview.replaceWith(nextPreview); enhanceImages(nextPreview); }
    const replaceDeleteModal = (nextDocument) => { const currentModal = document.getElementById('confirm-delete'); const nextModal = nextDocument.getElementById('confirm-delete'); if (currentModal && nextModal) currentModal.replaceWith(nextModal); else if (currentModal) currentModal.remove(); else if (nextModal) contextMenu.before(nextModal); };
    const navigateToNote = async (url, pushHistory = true) => { if (navigating) return; const targetUrl = new URL(url, window.location.href); if (pushHistory && targetUrl.href === window.location.href) return; if (!await saveQuietly()) { showToast(lastSaveError || t.couldNotSave, 'error'); return; } navigating = true; try { const response = await fetch(targetUrl.href, { headers: { 'X-Requested-With': 'XMLHttpRequest' } }); if (!response.ok) throw new Error(t.couldNotOpenNote); const nextDocument = new DOMParser().parseFromString(await response.text(), 'text/html'); const nextContent = nextDocument.querySelector('.content'); const nextTree = nextDocument.getElementById('tree'); if (!nextContent || !nextTree) throw new Error(t.couldNotOpenNote); document.querySelector('.content').replaceWith(nextContent); tree.innerHTML = nextTree.innerHTML; replaceDeleteModal(nextDocument); document.title = nextDocument.title; activePath = nextTree.querySelector('.tree-note.active')?.dataset.dragPath || null; if (pushHistory) window.history.pushState({}, '', targetUrl.href); bindTreeInteractions(); bindEditor(); enhanceImages(document.querySelector('.preview-pane')); bindMobileSidebarToggle(); bindThemeChoices(); setTheme(readTheme(), false); } catch (error) { showToast(error.message || t.couldNotOpenNote, 'error'); } finally { navigating = false; } };
    tree.addEventListener('click', (event) => { const link = event.target.closest('.tree-note'); if (!link || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return; event.preventDefault(); setMobileSidebar(false); navigateToNote(link.href); }); window.addEventListener('popstate', () => navigateToNote(window.location.href, false));
    bindEditor(); enhanceImages(document.querySelector('.preview-pane')); setInterval(() => { saveQuietly(); }, 8000); window.addEventListener('beforeunload', () => { saveQuietly(); });
</script>
